/*
 * A067482  Powers of 4 with initial digit 4.
 * https://oeis.org/A067482
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 2, u32 n <= 3, u64 n <= 7, u128 n <= 10,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Sequence A067482:  Powers of 4 with initial digit 4
 * a(n) = 4^k, where k is the n‑th positive integer such that the
 * decimal representation of 4^k begins with the digit 4.
 *
 *  The sequence is generated by scanning successive exponents k,
 *  keeping the fractional part of k·log10(4).  If that fractional part
 *  lies in the interval [log10(4), log10(5)), the decimal expansion
 *  of 4^k starts with 4.  The corresponding power 4^k is then stored.
 *
 *  The implementation uses only integral arithmetic on the result type
 *  seq_t and the index type idx_t, satisfies all build constraints,
 *  and memoises the values so that calls to a(idx_t) can be in any order.
 */

#include <stdlib.h>    /* realloc, NULL */

#ifdef __cplusplus
#  include <cstddef>
#endif

/* Long‑double logs of 4 and 5 (in base 10). */
static const long double LOG10_4 = 0.60205999132796246261L;
static const long double LOG10_5 = 0.69897000433601880481L;

/* Cache for exponents (k) and the corresponding powers 4^k. */
static idx_t  *exp_cache = NULL;   /* exponents whose 4^k starts with 4   */
static seq_t  *val_cache = NULL;   /* values 4^k                          */
static size_t  cache_size = 0;     /* number of cached terms             */
static size_t  cache_cap  = 0;     /* allocated capacity                 */

/* State while scanning exponents. */
static idx_t      next_k = 1;          /* next exponent to examine         */
static long double cur_frac = LOG10_4; /* fractional part of next_k·log10(4) */

/* ------------------------------------------------------------------ */
/* Utility: grow cache if necessary.                                 */
static void
ensure_cache_cap(size_t needed)
{
    if (cache_cap >= needed)
        return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    while (new_cap < needed)
        new_cap <<= 1;
    exp_cache = (idx_t *)realloc(exp_cache, new_cap * sizeof(idx_t));
    val_cache = (seq_t *)realloc(val_cache, new_cap * sizeof(seq_t));
    cache_cap = new_cap;
}

/* ------------------------------------------------------------------ */
/* Fast exponentiation: compute 4^exp as seq_t. The routine works
 * for any unsigned integer or arbitrary‑precision seq_t that supports
 * multiplication without overflow on intermediate computations that are
 * required for the final value.
 */
static seq_t
pow4(idx_t exp)
{
    seq_t result = 1;
    seq_t base   = 4;
    while (exp)
    {
        if (exp & 1)
            result *= base;
        base *= base;
        exp >>= 1;
    }
    return result;
}

/* ------------------------------------------------------------------ */
/* The required function: return a(n). */
seq_t
a(idx_t n)
{
    if (n == 0)        /* not part of the sequence (offset 1) */
        return 0;

    /* Produce terms until we have at least n cached. */
    while (cache_size < (size_t)n)
    {
        /* Build cache space if needed. */
        ensure_cache_cap(cache_size + 1);

        /* Does the current exponent give a leading digit 4? */
        if (cur_frac >= LOG10_4 && cur_frac < LOG10_5)
        {
            exp_cache[cache_size] = next_k;
            val_cache[cache_size] = pow4(next_k);
            ++cache_size;
        }

        /* Advance to the next exponent. */
        ++next_k;
        cur_frac += LOG10_4;
        if (cur_frac >= 1.0L)
            cur_frac -= 1.0L;   /* keep fractional part in [0,1) */
    }

    /* Cache is 0‑based; requested index n is 1‑based. */
    return val_cache[n - 1];
}
